// Studio v6 · organização da biblioteca (extraído do HTML v6).
// Mantido o mais próximo possível do original; alterações estão marcadas com "Fase 1".
/* Arenamon Studio v6 — organização sem abas repetidas, biblioteca e destinos lado a lado. */
(()=>{
'use strict';
const $=id=>document.getElementById(id), E=window.__importer;
const GROUPS=[
{id:'idle',name:'Idle',icon:'◈',slots:['idle']},
{id:'movement',name:'Movimento',icon:'➤',slots:['walk','run','walk_back','walk_left','walk_right','strafe_left','strafe_right','move_1','move_2','move_3','move_4']},
{id:'attack',name:'Ataques',icon:'✦',slots:['tackle','tackle_back']},
{id:'dodge',name:'Esquivas',icon:'↝',slots:['dodge_forward','dodge_back','dodge_left','dodge_right']},
{id:'guard',name:'Defesa',icon:'⬡',slots:['block_start','block','guard_impact','blocked','block_end']},
{id:'reaction',name:'Dano',icon:'⌁',slots:['hit','knockback','fall','death']},
{id:'aerial',name:'Saltos',icon:'↟',slots:['jump','land','recover','downed']},
{id:'extras',name:'Extras',icon:'◇',slots:['extra_1','extra_2','extra_3','extra_4']}
];
const NAMES={idle:'Parado / Idle',walk:'Caminhar',run:'Correr',walk_back:'Recuar',walk_left:'Caminhar esquerda',walk_right:'Caminhar direita',strafe_left:'Strafe esquerda',strafe_right:'Strafe direita',tackle:'Tackle (X)',tackle_back:'Tackle para trás',dodge_forward:'Esquiva frontal',dodge_back:'Esquiva traseira',dodge_left:'Esquiva esquerda',dodge_right:'Esquiva direita',block_start:'Entrar em defesa',block:'Defesa',guard_impact:'Impacto na defesa',blocked:'Bloqueio recebido',block_end:'Sair da defesa',hit:'Receber dano',knockback:'Lançamento',fall:'Queda',land:'Aterrissar',recover:'Recuperação',death:'Derrota',jump:'Salto',downed:'Levantar do chão'};
for(let i=1;i<=4;i++){NAMES['move_'+i]='Movimento '+i;NAMES['extra_'+i]='Alternativa '+i}
const escapeText=str=>String(str??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const clips=()=>E?.clips||[];
let meta=[],customActions=[],customCounter=1,selected=0,selectedCategory='attack',toastTimer=null,dragged=null,draggingOver=null,lastClipCount=-1;
function toast(msg){const n=$('toast');if(!n)return;n.textContent=msg;n.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('show'),2600)}
function ensureMeta(){while(meta.length<clips().length)meta.push({category:null,order:meta.length});meta.length=clips().length;if(selected>=clips().length)selected=Math.max(0,clips().length-1)}
function normalizeCat(cat){return GROUPS.some(g=>g.id===cat)?cat:null}
function members(cat){ensureMeta();return clips().map((clip,i)=>({clip,i,m:meta[i]})).filter(e=>e.m.category===cat).sort((a,b)=>a.m.order-b.m.order||a.i-b.i)}
function setOrder(ids,cat){ids.forEach((idx,order)=>{meta[idx].order=order;meta[idx].category=cat})}
function moveClip(idx,cat,before=null){ensureMeta();cat=normalizeCat(cat);if(!Number.isInteger(idx)||!clips()[idx])return;const old=meta[idx].category;const from=members(old).map(e=>e.i).filter(i=>i!==idx);const dest=(cat===old?from:members(cat).map(e=>e.i).filter(i=>i!==idx));if(old!==cat)setOrder(from,old);const at=dest.indexOf(before);dest.splice(at<0?dest.length:at,0,idx);setOrder(dest,cat);selected=idx;if(cat)selectedCategory=cat;render();window.__studioProject?.markDirty('organizar clipe');toast('Movido para '+(GROUPS.find(g=>g.id===cat)?.name||'Sem categoria'))}
function actionIndex(key){const custom=customActions.find(a=>a.id===key);if(custom)return Number.isInteger(custom.clipIndex)?custom.clipIndex:-1;return Number($('action-'+key)?.value??-1)}
function setAction(key,i){if(!Number.isInteger(i)||!clips()[i])return false;const custom=customActions.find(a=>a.id===key);const group=GROUPS.find(g=>g.slots.includes(key));if(custom)custom.clipIndex=i;else {const sel=$('action-'+key);if(!sel)return false;sel.value=String(i);sel.dispatchEvent(new Event('change',{bubbles:true}))}moveClip(i,custom?.category||group?.id||null);selected=i;window.__studioProject?.markDirty('vincular ação');toast('Vinculado a '+(custom?.name||NAMES[key]||key));return true}
function clearAction(key){const custom=customActions.find(a=>a.id===key);if(custom)custom.clipIndex=null;else{const sel=$('action-'+key);if(!sel)return;sel.value='-1';sel.dispatchEvent(new Event('change',{bubbles:true}))}render();window.__studioProject?.markDirty('desvincular ação')}
function preview(i){if(!clips()[i])return;selected=i;$('clip').value=String(i);$('clip').dispatchEvent(new Event('change',{bubbles:true}));if($('play')?.textContent?.includes('Reproduzir'))$('play').click();renderShelfOnly()}
function clipCard(i){const c=clips()[i],m=meta[i];const n=document.createElement('div');n.className='v6-clip'+(selected===i?' selected':'');n.draggable=true;n.dataset.clip=String(i);n.tabIndex=0;n.setAttribute('role','option');n.setAttribute('aria-selected',String(selected===i));n.title=c.sourceFile||c.name;
 n.innerHTML='<span class="v6-grip" aria-hidden="true">⠿</span><span class="v6-clip-body"><strong>'+escapeText(c.name)+'</strong><small>'+(m.category?escapeText(GROUPS.find(g=>g.id===m.category)?.name):'Sem categoria')+' · '+Number(c.duration||0).toFixed(1)+'s</small></span><button class="v6-preview" type="button" title="Reproduzir '+escapeText(c.name)+'" aria-label="Reproduzir '+escapeText(c.name)+'">▶</button><button class="v6-fav" type="button" title="Favoritar/desfavoritar" aria-label="Favoritar '+escapeText(c.name)+'">☆</button>';
 const star=n.querySelector('.v6-fav');const favored=window.__studioV4?.getFavorites?.().has(i)||false;star.textContent=favored?'★':'☆';star.setAttribute('aria-pressed',String(favored));star.onclick=e=>{e.stopPropagation();window.__studioV4?.toggleFavorite?.(i);renderShelfOnly()};
 n.onclick=()=>{selected=i;if($('clip')&&$('clip').value!==String(i)){$('clip').value=String(i);$('clip').dispatchEvent(new Event('change',{bubbles:true}))}renderShelfOnly();renderQuickAssign();window.__studioLayout?.selectContext?.('clip',i)};n.onkeydown=e=>{if(e.target!==n)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();selected=i;renderShelfOnly();renderQuickAssign();window.__studioLayout?.selectContext?.('clip',i)}};
 n.querySelector('.v6-preview').onclick=e=>{e.stopPropagation();preview(i)};
 n.addEventListener('dragstart',e=>{dragged=i;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('application/x-arenamon-clip',String(i));e.dataTransfer.setData('text/plain',String(i));n.classList.add('dragging');$('v6-board').classList.add('is-dragging')});
 n.addEventListener('dragend',()=>{dragged=null;document.querySelectorAll('.v6-drop-over,.v6-reorder-target').forEach(el=>el.classList.remove('v6-drop-over','v6-reorder-target'));$('v6-board').classList.remove('is-dragging')});
 return n;
}
function draggedClip(e){const raw=e.dataTransfer.getData('application/x-arenamon-clip')||e.dataTransfer.getData('text/plain');if(!/^\d+$/.test(raw))return null;const n=Number(raw);return clips()[n]?n:null}
function dropZone(el,onDrop){el.addEventListener('dragenter',e=>{if(dragged==null)return;e.preventDefault();el.classList.add('v6-drop-over')});el.addEventListener('dragover',e=>{if(dragged==null)return;e.preventDefault();e.dataTransfer.dropEffect='move';el.classList.add('v6-drop-over')});el.addEventListener('dragleave',e=>{if(!el.contains(e.relatedTarget))el.classList.remove('v6-drop-over')});el.addEventListener('drop',e=>{e.preventDefault();e.stopPropagation();el.classList.remove('v6-drop-over');const i=draggedClip(e);if(i!=null)onDrop(i)});}
function renderShelfOnly(){const q=($('clip-search')?.value||'').toLowerCase().trim();const list=$('v6-shelf-list');if(!list)return;list.replaceChildren();const faves=window.__studioV4?.getFavorites?.()||new Set();const matches=clips().map((c,i)=>({c,i})).filter(({c,i})=>(!$('v4-only-favorites').checked||faves.has(i))&&[c.name,c.sourceFile,GROUPS.find(g=>g.id===meta[i].category)?.name].some(v=>String(v||'').toLowerCase().includes(q)));const sort=$('v4-clip-sort').value;if(sort==='name')matches.sort((a,b)=>a.c.name.localeCompare(b.c.name,'pt'));else if(sort==='duration')matches.sort((a,b)=>(b.c.duration||0)-(a.c.duration||0));else if(sort==='favorites')matches.sort((a,b)=>Number(faves.has(b.i))-Number(faves.has(a.i)));
 for(let {i} of matches)list.append(clipCard(i));if(!matches.length){const e=document.createElement('p');e.className='v6-empty';e.textContent=clips().length?'Nenhum clipe corresponde à busca.':'Importe animações para começar.';list.append(e)}
 const counts=$('v6-shelf-count');if(counts)counts.textContent=matches.length+' de '+clips().length;
 $('clip-total').textContent=clips().length+' clipes';$('clip-assigned').textContent=meta.filter(m=>m.category).length+' classificados';$('clip-unassigned').textContent=meta.filter(m=>!m.category).length+' não classificados';
}
function renderQuickAssign(){const n=$('v6-selected-name'),cat=$('v6-category-select'),action=$('v6-action-select');if(!n||!cat||!action)return;
 const c=clips()[selected];n.textContent=c?c.name:'Escolha um clipe na lista';n.title=c?.sourceFile||'';cat.disabled=!c;action.disabled=!c;
 cat.innerHTML='<option value="">Sem categoria</option>'+GROUPS.map(g=>'<option value="'+g.id+'">'+escapeText(g.name)+'</option>').join('');cat.value=meta[selected]?.category||'';
 action.innerHTML='<option value="">Vincular a uma ação…</option>'+GROUPS.map(g=>'<optgroup label="'+escapeText(g.name)+'">'+[...g.slots,...customActions.filter(a=>a.category===g.id).map(a=>a.id)].map(key=>'<option value="'+escapeText(key)+'">'+escapeText(customActions.find(a=>a.id===key)?.name||NAMES[key]||key)+'</option>').join('')+'</optgroup>').join('');action.value='';
}
function renderTabs(){const tabs=$('v6-category-tabs');tabs.replaceChildren();const label=document.createElement('label');label.className='v6-category-chooser';label.setAttribute('for','v6-group-select');label.innerHTML='<span>Categoria de destino</span>';
 const select=document.createElement('select');select.id='v6-group-select';select.setAttribute('aria-label','Categoria cujas ações você deseja ver');select.innerHTML=GROUPS.map(g=>'<option value="'+g.id+'">'+g.icon+' '+g.name+'</option>').join('');select.value=selectedCategory;select.onchange=()=>{selectedCategory=select.value;renderTargets()};label.append(select);tabs.append(label);
}
function actionRow(key){const i=actionIndex(key),custom=customActions.find(a=>a.id===key),r=document.createElement('div');r.className='v6-slot';r.dataset.action=key;
 const content=document.createElement('div');content.className='v6-slot-title';content.innerHTML='<strong>'+escapeText(custom?.name||NAMES[key]||key)+'</strong><small>'+(i>=0&&clips()[i]?escapeText(clips()[i].name):'Arraste aqui ou escolha um clipe')+'</small>';
 const select=document.createElement('select');select.className='v6-slot-choice';select.setAttribute('aria-label','Animação para '+(custom?.name||NAMES[key]||key));select.innerHTML='<option value="-1">'+(i<0?'Escolher…':'Nenhuma')+'</option>'+clips().map((c,idx)=>'<option value="'+idx+'">'+escapeText(c.name)+'</option>').join('');select.value=i>=0?String(i):'-1';select.onchange=()=>{const idx=Number(select.value);idx>=0?setAction(key,idx):clearAction(key)};
 r.append(content,select);dropZone(r,idx=>setAction(key,idx));if(custom){const del=document.createElement('button');del.textContent='×';del.type='button';del.title='Excluir ação personalizada';del.className='v6-custom-delete';del.onclick=()=>{customActions=customActions.filter(a=>a.id!==key);render();window.__studioProject?.markDirty('excluir ação')};r.append(del)}return r;
}
function renderTargets(){renderTabs();const g=GROUPS.find(g=>g.id===selectedCategory)||GROUPS[0];$('v6-current-category').textContent=g.name;
 const target=$('v6-category-drop');target.querySelector('strong').textContent='Adicionar a '+g.name;target.querySelector('span').textContent='Solte aqui para classificar sem vincular a uma ação';target.classList.toggle('has-members',members(g.id).length>0);dropZoneOnce(target,i=>moveClip(i,g.id));
 const slotlist=$('v6-slots');slotlist.replaceChildren();for(const key of g.slots)slotlist.append(actionRow(key));for(const a of customActions.filter(a=>a.category===g.id))slotlist.append(actionRow(a.id));
 const cur=$('v6-category-members');cur.replaceChildren();const all=members(g.id);const used=new Set([...g.slots,...customActions.filter(a=>a.category===g.id).map(a=>a.id)].map(actionIndex).filter(i=>i>=0));const ordered=all.filter(({i})=>!used.has(i));$('v6-category-count').textContent=all.length+' classificados';for(const {i} of ordered){const c=document.createElement('div');c.className='v6-member';c.draggable=true;c.dataset.clip=String(i);c.innerHTML='<span class="v6-mini-grip">⠿</span><span title="'+escapeText(clips()[i].name)+'">'+escapeText(clips()[i].name)+'</span><button type="button" title="Remover da categoria" aria-label="Remover '+escapeText(clips()[i].name)+' da categoria">×</button>';c.querySelector('button').onclick=()=>moveClip(i,null);c.addEventListener('dragstart',e=>{dragged=i;e.dataTransfer.setData('application/x-arenamon-clip',String(i));e.dataTransfer.setData('text/plain',String(i));e.dataTransfer.effectAllowed='move'});c.addEventListener('dragend',()=>{dragged=null});dropZone(c,from=>{if(from!==i)moveClip(from,g.id,i)});cur.append(c)}
 $('v6-category-members-wrap').hidden=ordered.length===0;
}
function dropZoneOnce(target,callback){target.__dropCallback=callback;if(target.__dropRegistered)return;target.__dropRegistered=true;dropZone(target,i=>target.__dropCallback(i))}
function renderLegacyLibrary(){/* Mantém a superfície de favoritos/ordenação da v4 disponível para compatibilidade. */
 const list=$('clip-library');if(!list)return;const q=$('clip-search').value.toLowerCase().trim();list.replaceChildren();for(let i=0;i<clips().length;i++){const c=clips()[i];if(!q||[c.name,c.sourceFile].some(x=>String(x||'').toLowerCase().includes(q))){const wrap=document.createElement('div');const card=document.createElement('div');card.className='clip-card';card.dataset.clip=String(i);card.innerHTML='<span class="clip-name"><strong>'+escapeText(c.name)+'</strong></span>';wrap.append(card);list.append(wrap)}}}
function render(){ensureMeta();renderLegacyLibrary();renderShelfOnly();renderQuickAssign();renderTargets();$('stage-welcome').hidden=!!E?.model;if(E?.model){const badge=$('model-badge');if(badge){const value='◈ '+($('model').files[0]?.name||'Modelo carregado');if(badge.textContent!==value)badge.textContent=value}}}
function manifest(){ensureMeta();return {version:2,clips:clips().map((c,i)=>({clipIndex:i,clipName:c.name,sourceFile:c.sourceFile||c.name,category:meta[i].category,order:meta[i].order})),customActions:customActions.map(a=>({...a,clipName:clips()[a.clipIndex]?.name||null,sourceFile:clips()[a.clipIndex]?.sourceFile||null}))}}
function restore(data){meta=[];ensureMeta();const org=data?.organization;customActions=Array.isArray(org?.customActions)?org.customActions.filter(a=>typeof a?.name==='string'&&GROUPS.some(g=>g.id===a.category)).map(a=>{const idx=clips().findIndex((c,i)=>c.name===a.clipName||(c.sourceFile===a.sourceFile&&i===a.clipIndex));return {id:typeof a.id==='string'?a.id:'custom_'+customCounter++,name:a.name.slice(0,90),category:a.category,clipIndex:idx>=0?idx:null}}):[];
 customCounter=1+Math.max(0,...customActions.map(a=>Number(a.id.split('_')[1])||0));for(const item of org?.clips||[]){const i=Number(item.clipIndex);if(!Number.isInteger(i)||!meta[i]||!clips()[i])continue;const c=clips()[i];if(item.clipName&&c.name!==item.clipName&&item.sourceFile!==c.sourceFile)continue;meta[i]={category:normalizeCat(item.category),order:Number.isFinite(item.order)?item.order:i};if(item.sourceFile)c.sourceFile=item.sourceFile}render()}
function updateAppearance(){const p=$('palette').value==='global';$('paint-note').textContent=p?'Pintura global ativa: todas as malhas recebem a cor escolhida.':'Materiais originais ativos. Selecione Pintura global para aplicar uma cor ao personagem inteiro.';$('v6-paint-state').textContent=p?'Cor global aplicada':'Cores originais'}
$('clip-search').addEventListener('input',renderShelfOnly);for(const id of ['v4-clip-sort','v4-only-favorites'])$(id).addEventListener('change',renderShelfOnly);
$('v6-category-select').onchange=e=>{if(clips()[selected])moveClip(selected,e.target.value||null)};
$('v6-action-select').onchange=e=>{if(e.target.value&&clips()[selected])setAction(e.target.value,selected)};
$('v6-create-action').onsubmit=e=>{e.preventDefault();const input=$('v6-new-action');const name=input.value.trim();if(!name)return;customActions.push({id:'custom_'+customCounter++,name:name.slice(0,90),category:selectedCategory,clipIndex:null});input.value='';renderTargets();window.__studioProject?.markDirty('criar ação');toast('Ação criada: '+name)};
$('palette').addEventListener('change',updateAppearance);$('color').addEventListener('input',()=>queueMicrotask(updateAppearance));
// As áreas de importação continuam usando o mesmo handler real do motor.
for(const [id,dropId] of [['model','model-drop'],['animations','animation-drop']]){const input=$(id),zone=$(dropId);zone.addEventListener('dragover',e=>{if(!e.dataTransfer.types.includes('Files'))return;e.preventDefault();zone.classList.add('dragover')});zone.addEventListener('dragleave',()=>zone.classList.remove('dragover'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragover');const dt=new DataTransfer();for(const f of e.dataTransfer.files)if(/\.(fbx|glb)$/i.test(f.name))dt.items.add(f);if(!dt.files.length)return toast('Importe FBX ou GLB.');input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}))})}
$('welcome-import').onclick=()=>$('model').click();$('shortcut-help').onclick=()=>$('help-modal').hidden=false;$('close-help').onclick=()=>$('help-modal').hidden=true;$('help-modal').addEventListener('click',e=>{if(e.target===$('help-modal'))$('help-modal').hidden=true});
$('clip').addEventListener('change',()=>{const idx=Number($('clip').value);if(Number.isInteger(idx)&&clips()[idx]){selected=idx;renderShelfOnly();renderQuickAssign();if(window.__studioLayout?.mode==='animate'&&window.__studioLayout?.inspector?.kind!=='clips')window.__studioLayout?.selectContext?.('clip',idx)}});
new MutationObserver(()=>{if(lastClipCount!==clips().length){lastClipCount=clips().length;render()}}).observe($('clip'),{childList:true});
new MutationObserver(()=>{renderTargets()}).observe($('action-list'),{childList:true,subtree:true});
// Fase 1: remoção de clipes derivados desloca os índices da organização.
function onClipRemoved(index){ensureMeta();meta.splice(index,1);for(const a of customActions){if(a.clipIndex===index)a.clipIndex=null;else if(Number.isInteger(a.clipIndex)&&a.clipIndex>index)a.clipIndex--}if(selected>=index&&selected>0)selected--}
window.__arenamonOrganization={manifest,restore,refresh:render,moveClip,updateAppearance,onClipRemoved};
$('import-json-btn').onclick=()=>$('import-json-input').click();
$('import-json-input').onchange=async()=>{const input=$('import-json-input'),file=input.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!data||typeof data!=='object'||(!data.organization&&!data.clips))throw Error('JSON sem organização');const org=data.organization?data:{organization:data};restore(org);
 for(const [slot,assoc] of Object.entries({...org.actions,...org.extras})){if(!assoc)continue;const sel=$('action-'+slot);if(!sel)continue;const index=clips().findIndex(c=>c.name===assoc.clipName);if(index>=0){sel.value=String(index);sel.dispatchEvent(new Event('change',{bubbles:true}))}}
 if(Number.isFinite(org.randomAlternatives?.probability))$('alt-chance').value=String(Math.min(1,Math.max(0,org.randomAlternatives.probability))*100);window.__studioV3?.restore?.(org.preview||null);render();window.__studioProject?.markDirty('importar organização');toast('Organização importada')}catch(err){toast('Erro no JSON: '+err.message)}finally{input.value=''}};
updateAppearance();render();
})();
